import sys
lines = sys.stdin.read().splitlines()
if lines:
    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])
    words = lines[1:1+n]
    lookup = {}
    for idx, w in enumerate(words):
        l = len(w)
        for p_len in range(l + 1):
            for s_len in range(l + 1):
                lookup[(w[:p_len], w[l-s_len:])] = idx
    out = []
    for line in lines[1+n:1+n+m]:
        cmd = line.split()
        if len(cmd) == 2:
            out.append(str(lookup.get((cmd[0], cmd[1]), -1)))
    print(' '.join(out))
